ALLOWED_USER_FILTER_FIELDS = {"topic", "department"}

def build_secure_metadata_filter(client_filter: dict | None, auth_tenant_id: str, allowed_classifications: list[str]) -> dict:
    safe_filter: dict = {}
    if isinstance(client_filter, dict):
        for k, v in client_filter.items():
            # Reject any operator injection ($ne, $in) or security-critical field override
            if k in ALLOWED_USER_FILTER_FIELDS and isinstance(v, str) and not v.startswith("$"):
                safe_filter[k] = v
    # Mandatory server-side security predicates overwrite everything
    safe_filter["tenant_id"] = auth_tenant_id
    safe_filter["classification"] = {"$in": allowed_classifications}
    return safe_filter
